.lll-whats-new{margin:0;color:var(--ink);background:var(--bg);font-family:var(--sans);line-height:1.65;font-size:22px;font-weight:300}.lll-whats-new img{max-width:100%;height:auto;display:block}.lll-whats-new a{color:inherit}.lll-whats-new,.lll-whats-new *,.lll-whats-new,.lll-whats-new *,.lll-whats-new,.lll-whats-new *{box-sizing:border-box}.lll-whats-new{margin:0;color:var(--ink);background:var(--bg);font-family:var(--sans);line-height:1.65}.lll-whats-new img{max-width:100%;display:block}.lll-whats-new a{color:inherit}.lll-whats-new .wrap{width:min(1180px,calc(100% - 40px));margin-inline:auto}.lll-whats-new .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;text-decoration:none;border:0;border-radius:999px;padding:12px 36px;font-family:var(--sans);font-weight:500;font-size:14px;letter-spacing:.06em;text-transform:uppercase;line-height:1.2;box-shadow:none;transition:transform .3s ease,box-shadow .3s ease,filter .3s ease,background-color .3s ease}.lll-whats-new .btn-primary{background:var(--accent);color:#fff}.lll-whats-new .btn-primary:hover{transform:translateY(-2px) scale(1.02);box-shadow:0 10px 22px rgba(196,75,106,.32);filter:brightness(1.08)}.lll-whats-new .btn-primary:active{transform:translateY(0) scale(1)}.lll-whats-new .section{padding:72px 0}.lll-whats-new h1,.lll-whats-new h2,.lll-whats-new h3{line-height:1.25;margin:0 0 .45em;font-weight:500}.lll-whats-new .lead{max-width:62ch}.lll-whats-new .card{text-decoration:none;display:flex;flex-direction:column;overflow:hidden;background:var(--card);color:var(--ink);transition:transform .4s cubic-bezier(.22,1,.36,1),box-shadow .4s ease}.lll-whats-new .card:hover{transform:translateY(-10px);box-shadow:0 22px 48px rgba(80,30,40,.16)}.lll-whats-new .card-media{aspect-ratio:16/10;overflow:hidden}.lll-whats-new .card-media img{width:100%;height:100%;object-fit:cover;transition:transform .6s cubic-bezier(.22,1,.36,1)}.lll-whats-new .card:hover .card-media img{transform:scale(1.08)}.lll-whats-new .card-body{padding:16px 18px 20px}.lll-whats-new .card time{font-size:12px;letter-spacing:.08em;text-transform:uppercase;opacity:.65}.lll-whats-new .card h3{font-family:"Libre Baskerville",Georgia,serif;font-size:20px;font-weight:600;margin:.35em 0 .6em;line-height:1.3}.lll-whats-new .more{font-size:13px;font-weight:700;color:var(--accent);display:inline-flex;align-items:center;gap:6px}.lll-whats-new .more::after{content:"→";transition:transform .3s ease}.lll-whats-new .card:hover .more::after,.lll-whats-new .spot-card:hover .more::after{transform:translateX(4px)}.lll-whats-new .form{display:flex;gap:8px;flex-wrap:wrap}.lll-whats-new .form input{flex:1;min-width:220px;padding:14px 16px;border:1px solid #d8cfd3;border-radius:10px;font:inherit}.lll-whats-new .form button{border:0;background:var(--accent);color:#fff;padding:12px 36px;border-radius:999px;font-family:var(--sans);font-weight:500;font-size:14px;letter-spacing:.06em;text-transform:uppercase;cursor:pointer;box-shadow:none;transition:transform .3s ease,box-shadow .3s ease,filter .3s ease}.lll-whats-new .form button:hover{transform:translateY(-2px) scale(1.02);box-shadow:0 10px 22px rgba(196,75,106,.32);filter:brightness(1.08)}.lll-whats-new .quote-frame img{transition:transform .6s cubic-bezier(.22,1,.36,1)}.lll-whats-new .quote-frame:hover img{transform:scale(1.04)}.lll-whats-new .wash-panel{transition:transform .4s cubic-bezier(.22,1,.36,1),box-shadow .4s ease}.lll-whats-new .wash-panel:hover{transform:translateY(-4px);box-shadow:0 24px 48px rgba(60,20,30,.14)}.lll-whats-new .paper{transition:box-shadow .4s ease}.lll-whats-new .cover:focus-visible,.lll-whats-new .card:focus-visible,.lll-whats-new .spot-card:focus-visible,.lll-whats-new .btn:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.lll-whats-new .footer{padding:40px 0;font-size:13px;opacity:.7}.lll-whats-new .mag{display:grid;grid-template-columns:1.45fr 1fr 1fr;grid-template-rows:auto auto;gap:18px}.lll-whats-new .mag .card{border-radius:16px;background:#fff;box-shadow:0 14px 36px rgba(80,30,40,.08)}.lll-whats-new .mag .card.is-feature{grid-column:1;grid-row:1 / span 2;display:flex;flex-direction:column;height:100%}.lll-whats-new .mag .card.is-feature .card-media{aspect-ratio:auto;flex:1;min-height:280px}.lll-whats-new .mag .card.is-feature h3{font-size:20px;font-family:"Libre Baskerville",Georgia,serif;font-weight:600}.lll-whats-new .cover{position:relative;min-height:280px;border-radius:18px;overflow:hidden;display:block;text-decoration:none;color:#fff;transition:transform .4s cubic-bezier(.22,1,.36,1),box-shadow .4s ease}.lll-whats-new .cover:hover{transform:translateY(-8px);box-shadow:0 20px 40px rgba(40,16,28,.22)}.lll-whats-new .cover>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .7s cubic-bezier(.22,1,.36,1)}.lll-whats-new .cover:hover>img{transform:scale(1.08)}.lll-whats-new .cover-grad{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:flex-end;align-items:flex-start;padding:18px;background:linear-gradient(180deg,rgba(40,16,28,.05),rgba(40,16,28,.78));transition:background .4s ease}.lll-whats-new .cover:hover .cover-grad{background:linear-gradient(180deg,rgba(40,16,28,.02),rgba(40,16,28,.88))}.lll-whats-new .cover h3{font-size:20px;margin:8px 0 0;font-family:"Libre Baskerville",Georgia,serif;font-weight:600}.lll-whats-new .cover .partner-logo{height:64px;width:auto;max-width:240px;object-fit:contain;background:#fff;border-radius:10px;padding:10px 16px;align-self:flex-start;flex:none;box-shadow:0 6px 16px rgba(0,0,0,.12)}:root,.lll-whats-new{
  --bg:#f6efe8; --ink:#2a1c22; --accent:#c44b6a; --card:#fff;
  --sans:"Montserrat",system-ui,sans-serif; --serif:"Libre Baskerville",Georgia,serif;
}.lll-whats-new{font-size:22px;font-weight:300;line-height:1.65}.lll-whats-new h1,.lll-whats-new h2,.lll-whats-new h3,.lll-whats-new .serif{font-family:var(--sans);font-weight:500}.lll-whats-new h2{font-size:clamp(28px,3vw,42px)}.lll-whats-new h3{font-size:clamp(22px,2vw,32px)}.lll-whats-new p,.lll-whats-new .lead,.lll-whats-new .hero-sub,.lll-whats-new .more,.lll-whats-new .card time,.lll-whats-new .spot-card time,.lll-whats-new .spot-card p,.lll-whats-new .form input{font-family:var(--sans)}.lll-whats-new p{font-size:22px;font-weight:300;margin:0 0 1em}

/* 1) Hero: text on the right so the face stays clear */
.hero-cine{min-height:88vh;position:relative;display:flex;align-items:flex-end;color:#fff}.lll-whats-new .hero-cine .hero-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:18% center}.lll-whats-new .hero-cine::after{content:"";position:absolute;inset:0;background:linear-gradient(270deg,rgba(32,14,22,.86) 0%, rgba(32,14,22,.55) 38%, rgba(32,14,22,.08) 62%, transparent 78%)}.lll-whats-new .hero-cine .wrap{position:relative;z-index:1;padding:48px 0 80px;display:flex;justify-content:flex-end}.lll-whats-new .hero-copy{width:min(540px,100%)}.lll-whats-new .hero-cine h1{font-size:60px;line-height:1.15;text-transform:uppercase;font-weight:500}.lll-whats-new .hero-cine h1 em{font-style:normal;color:#f3c2ce}.lll-whats-new .hero-sub{font-size:25px;font-weight:500;margin:0 0 18px}.lll-whats-new .paper{background:#fffaf6;border-radius:28px;padding:40px;margin-top:-56px;position:relative;z-index:2;box-shadow:0 24px 50px rgba(60,20,30,.12)}.lll-whats-new .split{display:grid;grid-template-columns:1fr 1fr;gap:36px}.lll-whats-new .covers{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}

/* 2) Spotlight: cinematic left copy, featured card on the right */
.spotlight{position:relative;min-height:560px;color:#fff;overflow:hidden;margin-top:48px}.lll-whats-new .spotlight .cine-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.lll-whats-new .spotlight::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(32,14,22,.78) 0%, rgba(32,14,22,.45) 48%, rgba(32,14,22,.2) 100%)}.lll-whats-new .spotlight .wrap{position:relative;z-index:1;display:grid;grid-template-columns:1.15fr .85fr;gap:36px;align-items:center;padding:56px 0}.lll-whats-new .spot-copy h2{font-size:clamp(28px,3vw,42px);max-width:18ch}.lll-whats-new .spot-copy .quote{font-size:clamp(22px,2vw,32px);font-weight:500;max-width:40ch}.lll-whats-new .spot-card{background:#fff;color:var(--ink);border-radius:20px;overflow:hidden;text-decoration:none;box-shadow:0 20px 50px rgba(0,0,0,.28);display:block;transition:transform .4s cubic-bezier(.22,1,.36,1),box-shadow .4s ease}.lll-whats-new .spot-card:hover{transform:translateY(-8px);box-shadow:0 28px 56px rgba(0,0,0,.35)}.lll-whats-new .spot-card img{width:100%;height:260px;object-fit:cover;transition:transform .6s cubic-bezier(.22,1,.36,1)}.lll-whats-new .spot-card:hover img{transform:scale(1.06)}.lll-whats-new .spot-card .body{padding:18px 20px 22px}.lll-whats-new .spot-card time{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--accent);font-weight:700}.lll-whats-new .spot-card h3{font-family:"Libre Baskerville",Georgia,serif;font-size:20px;font-weight:600;margin:.35em 0 .5em}.lll-whats-new .spot-card p{font-size:16px}

/* 3) Education: original section background as a photo header */
.photo-header{position:relative;min-height:520px;color:#fff;overflow:hidden}.lll-whats-new .photo-header img.bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:18% center}.lll-whats-new .photo-header::after{content:"";position:absolute;inset:0;background:linear-gradient(270deg,rgba(18,8,14,.96) 0%, rgba(18,8,14,.92) 28%, rgba(18,8,14,.78) 46%, rgba(18,8,14,.28) 68%, rgba(18,8,14,.06) 82%, transparent 94%)}.lll-whats-new .photo-header .wrap{position:relative;z-index:1;padding:64px 0 48px;display:flex;justify-content:flex-end}.lll-whats-new .photo-header .edu-copy{width:min(620px,100%);text-shadow:0 2px 16px rgba(10,4,8,.45)}.lll-whats-new .photo-header h2{font-size:clamp(28px,2vw,40px);max-width:18ch}

/* 4) Discussions: original photo as a left portrait pane */
.chapter{display:grid;grid-template-columns:.92fr 1.08fr;min-height:480px;background:#2a1c22;color:#fff;overflow:hidden}.lll-whats-new .chapter .pane{min-height:420px;object-fit:cover;width:100%;height:100%;transition:transform 1.2s ease}.lll-whats-new .chapter:hover .pane{transform:scale(1.04)}.lll-whats-new .chapter .copy{padding:56px 48px;display:flex;flex-direction:column;justify-content:center}.lll-whats-new .chapter h2{font-size:clamp(28px,2vw,40px)}

/* 5) Survivors: original photo as a soft full-bleed wash behind a cream panel */
.wash{position:relative;padding:72px 0;overflow:hidden}.lll-whats-new .wash .bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:saturate(1.05)}.lll-whats-new .wash::after{content:"";position:absolute;inset:0;background:rgba(246,239,232,.82)}.lll-whats-new .wash .wrap{position:relative;z-index:1}.lll-whats-new .wash-panel{background:rgba(255,250,246,.92);border-radius:28px;padding:36px;box-shadow:0 18px 40px rgba(60,20,30,.1);margin-bottom:28px}

/* 6) Blogs: original photo as a framed magazine opener beside the title */
.blog-open{display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:center}.lll-whats-new .blog-open .frame{border-radius:28px 4px 28px 4px;overflow:hidden;min-height:380px}.lll-whats-new .blog-open .frame img{width:100%;height:100%;object-fit:cover;min-height:380px;transition:transform .8s ease}.lll-whats-new .blog-open:hover .frame img{transform:scale(1.05)}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{transition:none !important}
  .card:hover,.cover:hover,.spot-card:hover,.wash-panel:hover,.btn:hover,.form button:hover{transform:none}
  .card:hover .card-media img,.cover:hover>img,.spot-card:hover img,.chapter:hover .pane,.blog-open:hover .frame img,.quote-frame:hover img{transform:none}
}.lll-whats-new .quote-frame{display:grid;grid-template-columns:200px 1fr;gap:28px;align-items:center;background:#2a1c22;color:#fff;border-radius:28px;padding:28px}.lll-whats-new .quote-frame img{width:200px;height:240px;object-fit:cover;border-radius:18px}.lll-whats-new .quote-frame blockquote{font-family:"Libre Baskerville",Georgia,serif;font-size:22px;font-weight:500;font-style:italic;margin:0}

@media (max-width:900px){
  .split,.covers,.spotlight .wrap,.chapter,.blog-open,.quote-frame,.mag{grid-template-columns:1fr}
  .mag .card.is-feature{grid-column:1 / -1;grid-row:auto}
  .hero-cine{min-height:72vh}
  .hero-cine h1{font-size:36px}
  .hero-cine .wrap,.photo-header .wrap{justify-content:flex-start}
  .hero-cine::after{background:linear-gradient(180deg,transparent 18%, rgba(32,14,22,.86))}
  .photo-header::after{background:linear-gradient(180deg,rgba(18,8,14,.2) 0%, rgba(18,8,14,.72) 32%, rgba(18,8,14,.94) 100%)}
  .chapter{grid-template-columns:1fr}
  .chapter .pane{min-height:280px}
}
@media (max-width:767px){
  body,p,.lead{font-size:20px}
}
